Thank you for the update. It seems that simple combinations of the X columns using basic operations don't yield an exact match for Y. Let's try a more complex approach using a combination of operators. We'll create a function to generate and test more complex expressions.

<python>
import pandas as pd
import numpy as np
import itertools

def apply_operator(op, *args):
    if op == 'add':
        return args[0] + args[1]
    elif op == 'subtract':
        return args[0] - args[1]
    elif op == 'multiply':
        return args[0] * args[1]
    elif op == 'divide':
        return args[0] / args[1]
    elif op == 'maximum':
        return np.maximum(args[0], args[1])
    elif op == 'minimum':
        return np.minimum(args[0], args[1])
    elif op == 'sqrt':
        return np.sqrt(args[0])
    elif op == 'log':
        return np.log(args[0])
    elif op == 'abs':
        return np.abs(args[0])
    elif op == 'negative':
        return -args[0]
    elif op == 'inverse':
        return 1 / args[0]
    elif op == 'sine':
        return np.sin(args[0])
    elif op == 'cosine':
        return np.cos(args[0])
    elif op == 'tangent':
        return np.tan(args[0])

def generate_and_test_expressions(data, max_depth=3):
    X1, X2, X3, X4, X5, Y = data['X1'], data['X2'], data['X3'], data['X4'], data['X5'], data['Y']
    variables = [X1, X2, X3, X4, X5]
    var_names = ['X1', 'X2', 'X3', 'X4', 'X5']

    binary_ops = ['add', 'subtract', 'multiply', 'divide', 'maximum', 'minimum']
    unary_ops = ['sqrt', 'log', 'abs', 'negative', 'inverse', 'sine', 'cosine', 'tangent']

    def generate_expressions(depth):
        if depth == 0:
            return list(zip(var_names, variables))

        expressions = []

        for op in binary_ops:
            for left in generate_expressions(depth - 1):
                for right in generate_expressions(depth - 1):
                    expr = f"{op}({left[0]}, {right[0]})"
                    result = apply_operator(op, left[1], right[1])
                    expressions.append((expr, result))

        for op in unary_ops:
            for sub_expr in generate_expressions(depth - 1):
                expr = f"{op}({sub_expr[0]})"
                result = apply_operator(op, sub_expr[1])
                expressions.append((expr, result))

        return expressions

    for depth in range(1, max_depth + 1):
        print(f"Testing expressions of depth {depth}")
        expressions = generate_expressions(depth)
        for expr, result in expressions:
            diff = np.abs(Y - result)
            max_diff = np.max(diff)
            if max_diff < 1e-6:
                print(f"Match found: Y = {expr}")
                return expr

    print("No exact match found")
    return None

# Read the CSV file
data = pd.read_csv('data.csv')

# Generate and test expressions
result = generate_and_test_expressions(data)

