Now let's modify the Field classes to add type validation. We'll update fields.py:

<python>
with open('/home/agent/app/fields.py', 'r') as f:
    content = f.read()

new_content = """class Field:
    def __init__(self, field_type):
        self.field_type = field_type
        self._value = None

    def declaration(self, name):
        return f"{name} {self.field_type}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return instance.__dict__.get(self.name, None)

    def __set__(self, instance, value):
        self.validate(value)
        instance.__dict__[self.name] = value

    def validate(self, value):
        pass

    def __set_name__(self, owner, name):
        self.name = name

class PrimaryKeyField(Field):
    def __init__(self):
        super().__init__("INTEGER PRIMARY KEY")

class IntegerField(Field):
    def __init__(self):
        super().__init__("INTEGER")

    def validate(self, value):
        if value is not None and not isinstance(value, int):
            raise ValueError(f"Field {self.name} must be an integer")

class StringField(Field):
    def __init__(self):
        super().__init__("TEXT")

    def validate(self, value):
        if value is not None and not isinstance(value, str):
            raise ValueError(f"Field {self.name} must be a string")

class ForeignKeyField(Field):
    def __init__(self, reference_model):
        self.reference_model = reference_model
        super().__init__("INTEGER")

    def declaration(self, name):
        ref_table = self.reference_model.__name__
        return super().declaration(name) + f" REFERENCES {ref_table}(id)"

    def validate(self, value):
        if value is not None and not isinstance(value, int):
            raise ValueError(f"Field {self.name} must be an integer")
"""

with open('/home/agent/app/fields.py', 'w') as f:
    f.write(new_content)

