import PyPDF2

def read_pdf():
    try:
        with open('alphacode2_report.pdf', 'rb') as file:
            pdf_reader = PyPDF2.PdfReader(file)
            text = ""
            for page in pdf_reader.pages:
                text += page.extract_text()

            # Search for relevant sections about Codeforces
            lines = text.split('\n')
            for i, line in enumerate(lines):
                if 'codeforce' in line.lower() or 'solve' in line.lower():
                    print(f"Context: {' '.join(lines[max(0, i-2):min(len(lines), i+3)])}")
    except Exception as e:
        print(f"Error: {e}")

