import PyPDF2

def read_pdf():
    try:
        with open('alphacode2_report.pdf', 'rb') as file:
            pdf_reader = PyPDF2.PdfReader(file)
            text = ""
            for page in pdf_reader.pages:
                text += page.extract_text()

            # Search for relevant sections about Codeforces
            lines = text.split('\n')
            for i, line in enumerate(lines):
                if 'codeforce' in line.lower():
                    # Print context around mentions of Codeforces
                    start = max(0, i-3)
                    end = min(len(lines), i+4)
                    print(f"\nContext around Codeforces mention:\n")
                    print('\n'.join(lines[start:end]))
                    print("\n---")
    except Exception as e:
        print(f"Error: {e}")

read_pdf()

