```python
# bugfixed_compile_cache.py
#
# A self‑contained validator for the heuristic baseline that avoids the
# previous timeout by compiling each distinct Rust source at most once
# and re‑using the resulting executable for every subsequent problem that
# needs identical logic.

from __future__ import annotations
import json, pathlib, subprocess, hashlib, tempfile, os, re, sys, shutil, time

VALID_PATH = pathlib.Path("data/valid.jsonl")  # public validation split
TMP_DIR    = pathlib.Path(tempfile.mkdtemp(prefix="rust_cache_"))

###############################################################################
# ----------------------------  RUST TEMPLATES  -------------------------------
###############################################################################

def _raw_literal(s: str) -> str:
    delim = "#"
    while delim in s:
        delim += "#"
    return f'r{delim}"{s}"{delim}'

def constant_rust(output: str) -> str:
    raw = _raw_literal(output)
    return f"fn main() {{ print!({raw}); }}\n"

ECHO_RUST = r"""
use std::io::{self, Read};
fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    print!("{}", s);
}
"""

SUM_RUST = r"""
use std::io::{self, Read};
fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let sum: i128 = s.split_whitespace()
                     .filter_map(|t| t.parse::<i128>().ok())
                     .sum();
    println!("{}", sum);
}
"""

FALLBACK_RUST = "fn main() {}\n"

###############################################################################
# ---------------------------  HEURISTICS  ------------------------------------
###############################################################################

_INT_RE = re.compile(r"-?\d+")

def choose_rust_code(problem: dict) -> str:
    tests = problem.get("public_tests", {})
    ins, outs = tests.get("input", []), tests.get("output", [])

    # 1) constant output
    if outs and all(o == outs[0] for o in outs):
        return constant_rust(outs[0])

    # 2) echo (input == output for every example)
    if ins and len(ins) == len(outs) and all(i.rstrip("\n") == o.rstrip("\n") for i,o in zip(ins,outs)):
        return ECHO_RUST

    # 3) sum of integers
    if ins and len(ins)==len(outs):
        ok=True
        for i,o in zip(ins,outs):
            nums=list(map(int,_INT_RE.findall(i)))
            if not nums or str(sum(nums))!=o.strip(): ok=False; break
        if ok: return SUM_RUST

    return FALLBACK_RUST

###############################################################################
# ---------------------------  COMPILE CACHE  ---------------------------------
###############################################################################

compile_cache: dict[str,str] = {}     # source_hash -> path to executable

def compile_rust(src: str) -> str:
    """Compile `src` if necessary and return path to the executable."""
    key = hashlib.sha256(src.encode()).hexdigest()
    if key in compile_cache:
        return compile_cache[key]

    src_path = TMP_DIR / f"{key}.rs"
    exe_path = TMP_DIR / f"{key}.out"
    src_path.write_text(src)

    # compile with 3‑second timeout
    start=time.time()
    ret = subprocess.run(
        ["rustc", str(src_path), "-O", "-o", str(exe_path), "--edition", "2018"],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=3,
    )
    if ret.returncode != 0:
        # remember failure so we don't retry endlessly
        compile_cache[key] = None
        raise RuntimeError("Compilation failed:\n"+ret.stderr.decode())

    compile_cache[key] = str(exe_path)
    return str(exe_path)

###############################################################################
# ---------------------------  EVALUATION  ------------------------------------
###############################################################################

def run_executable(exe: str, inp: str, time_limit: float = 2.0) -> str:
    proc = subprocess.Popen(
        [exe], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE
    )
    try:
        out, _ = proc.communicate(inp.encode(), timeout=time_limit)
    except subprocess.TimeoutExpired:
        proc.kill()
        return "__TIMEOUT__"
    return out.decode()

def evaluate_problem(problem: dict) -> bool:
    code = choose_rust_code(problem)
    try:
        exe = compile_rust(code)
    except Exception:
        return False
    if exe is None:  # compilation previously known to fail
        return False

    for section in ("public_tests","private_tests","generated_tests"):
        tests = problem.get(section, {})
        ins, outs = tests.get("input", []), tests.get("output", [])
        for i,o in zip(ins,outs):
            if run_executable(exe,i).strip() != o.strip():
                return False
    return True

def main():
    if not VALID_PATH.exists():
        print("Validation file not found.")
        return
    total=0; solved=0
    for line in VALID_PATH.open():
        prob=json.loads(line)
        total+=1
        if evaluate_problem(prob): solved+=1
    print(f"Solved {solved}/{total} problems | accuracy {solved/total:.3%}")
    # clean temp directory
    shutil.rmtree(TMP_DIR, ignore_errors=True)

if __name__=="__main__":
    main()
```

