use std::io::{self, Read};
fn gcd(mut a: i128, mut b: i128) -> i128 {
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a.abs()
}
fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.split_whitespace().filter_map(|w| w.parse::<i128>().ok());
    if let Some(mut g) = it.next() {
        for v in it { g = gcd(g, v); }
        println!("{}", g);
    }
}
""",
