cat << 'EOF' > solution/improved_solve_code_contests_rust.py
const MOD: i64 = 1_000_000_007;

fn pow_mod(mut base: i64, mut exp: i64) -> i64 {
    let mut result = 1;
    while exp > 0 {
        if exp & 1 != 0 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let mut iter = input.split_whitespace();
    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let inv3 = pow_mod(3, MOD-2);
    let mut dp = vec![0; 3*n+1];
    dp[0] = n as i64;
    for i in 1..=3*n {
        dp[i] = ((3 * n as i64 * pow_mod(3, i as i64 - 1) % MOD - dp[i-1] + MOD) % MOD * inv3) % MOD;
    }

    for _ in 0..q {
        input.clear();
        std::io::stdin().read_line(&mut input).unwrap();
        let x: usize = input.trim().parse().unwrap();
        println!("{}", dp[x]);
    }
}
