```python
from __future__ import annotations

import asyncio
import logging
from typing import Any
import json

import backoff
import openai
from rust_codecontests_utils import evaluate_rust_code

logging.getLogger("backoff").addHandler(logging.StreamHandler())

openai.api_key_path = "api_key.txt"


def get_prompt(problem):
    examples = [
        {
            "description": """Write a program that reads two integers A and B and prints their sum.

Constraints:
- -10^9 ≤ A, B ≤ 10^9

Input Format:
The first line contains two space-separated integers A and B.

Output Format:
Output a single integer representing the sum of A and B.""",
            "solution": """use std::io;

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let nums: Vec<i64> = input.trim().split_whitespace()
        .map(|x| x.parse().unwrap())
        .collect();
    println!("{}", nums[0] + nums[1]);
}""",
        },
        {
            "description": """Given an integer N, print "Yes" if N is even, otherwise print "No".

Constraints:
- 0 ≤ N ≤ 100

Input Format:
A single integer N.

Output Format:
Print "Yes" if N is even, otherwise print "No".""",
            "solution": """use std::io;

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let n: i32 = input.trim().parse().unwrap();
    if n % 2 == 0 {
        println!("Yes");
    } else {
        println!("No");
    }
}""",
        },
    ]

    example_text = ""
    for ex in examples:
        example_text += (
            f"Problem:\n{ex['description']}\nSolution:\n{ex['solution']}\n\n"
        )

    prompt = f"""{example_text}
Now, please solve the following problem in Rust. Output only the Rust code for the solution, without any explanations, comments, or code delimiters.

Problem:
{problem['description']}

Solution:"""

    return prompt


def get_system_message():
    system_message = (
        "You are an expert competitive programmer who writes correct and optimized Rust code to solve coding contest problems. Carefully read the problem description and produce code that meets all constraints and requirements. Do not include any explanations or comments, and output only the code."
    )
    return system_message


@backoff.on_exception(
    backoff.expo,
    Exception,
    max_time=300,
)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
) -> str:
    prompt = get_prompt(problem)
    system_message = get_system_message()
    async with semaphore:
        completion = await client.chat_completions.create(
            model="gpt-3.5-turbo-0125",
            max_tokens=1600,
            temperature=0,
            messages=[
                {"role": "system", "content": system_message},
                {"role": "user", "content": prompt},
            ],
        )
        code = completion.choices[0].message.content.strip()
        # Remove any code delimiters
        if code.startswith("```"):
            code = code.strip("```").strip()
    return code


async def process_problem(client, semaphore, problem):
    code = await generate_solution(client, semaphore, problem)
    result = await evaluate_rust_code(semaphore, problem, code, scratch_dir="./working")
    return result


async def main():
    semaphore = asyncio.Semaphore(5)
    client = openai.AsyncOpenAI()

    with open("data/valid.jsonl", "r") as f:
        problems = [json.loads(line) for line in f]

    tasks = [process_problem(client, semaphore, problem) for problem in problems]

    results = await asyncio.gather(*tasks)

    successes = sum(1 for result in results if result["succeeded"])
    total = len(problems)

    evaluation_metric = successes / total if total > 0 else 0
    print(f"Evaluation Metric (Accuracy): {evaluation_metric}")


if __name__ == "__main__":
    asyncio.run(main())
```

