def get_prompt(problem: dict[str, Any]) -> str:
    # Include test cases in prompt if available
    examples = ""
    if "public_tests" in problem:
        tests = problem["public_tests"]
        for i, (inp, out) in enumerate(zip(tests.get("input", []), tests.get("output", []))):
            examples += f"\nTest Case {i+1}:\nInput:\n{inp}\nExpected Output:\n{out}\n"

    return f"""Solve this coding problem in Rust:

Problem: {problem['description']}

Input/Output Format:{examples}

Requirements:
1. Read input from stdin (use std::io)
2. Write output to stdout
3. Handle all input parsing robustly
4. Match the exact output format shown
5. Use Rust 2018 edition syntax

Return only the complete, compilable Rust solution."""

@backoff.on_exception(
    backoff.expo,
    Exception,
    max_time=300,
)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
) -> str:
    system_msg = """You are an expert Rust programmer. Generate clean, efficient Rust code that:
    - Uses proper stdin/stdout handling
    - Implements robust error handling
    - Follows Rust best practices
    - Is fully compilable
    - Matches the exact output format required
    Provide only the code without explanations."""

    async with semaphore:
        completion = await client.chat.completions.create(
            model="gpt-3.5-turbo-0125",
            messages=[
                {"role": "system", "content": system_msg},
                {"role": "user", "content": get_prompt(problem)}
            ],
            max_tokens=1600,
            temperature=0.2,
        )

    return extract_rust_code(completion.choices[0].message.content)
