The main issue with the previous implementation is improper handling of the markdown code formatting and an incomplete problem description in the prompt. We need to fix this by improving the prompt structure to include test cases and requirements, adding proper code cleaning logic, and using the response_format parameter to get clean code output. Additionally, we'll lower the temperature for more consistent results and add better error handling.

```python
from __future__ import annotations
import asyncio
import logging
from typing import Any
import backoff
import openai

logging.getLogger("backoff").addHandler(logging.StreamHandler())

def get_formatted_tests(problem):
    tests = []
    if 'public_tests' in problem:
        for i, (inp, out) in enumerate(zip(problem['public_tests']['input'], 
                                         problem['public_tests']['output'])):
            tests.append(f"Test {i+1}:\nInput:\n{inp}\nExpected Output:\n{out}\n")
    return "\n".join(tests)

def get_prompt(problem):
    return f"""Write a solution in Rust for the following coding problem:

Problem: {problem['name']}
Description: {problem['description']}

Example Tests:
{get_formatted_tests(problem)}

Requirements:
1. Use Rust 2018 edition syntax
2. Include all necessary imports
3. Handle all input/output using standard input/output
4. Follow exact input/output format shown in examples
5. Handle edge cases and invalid input
6. Use appropriate data types and error handling

Provide only the complete, compilable Rust code without any explanations."""

@backoff.on_exception(
    backoff.expo,
    Exception,
    max_time=300,
)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
) -> str:
    async with semaphore:
        response = await client.chat.completions.create(
            model="gpt-3.5-turbo-0125",
            messages=[
                {"role": "system", "content": "You are an expert Rust programmer. Provide only compilable Rust code without any markdown formatting or explanations."},
                {"role": "user", "content": get_prompt(problem)}
            ],
            max_tokens=1600,
            temperature=0.2,
            response_format={"type": "text"}
        )

    code = response.choices[0].message.content.strip()

    # Clean any remaining markdown artifacts
    if code.startswith("```rust"):
        code = code[7:]
    elif code.startswith("```"):
        code = code[3:]
    if code.endswith("```"):
        code = code[:-3]

    return code.strip()
```

