Running this file as a script performs a quick validation-set check and prints
the fraction of problems fully solved.
"""

from __future__ import annotations

import asyncio
import json
import os
import re
import tempfile
from typing import Any, Callable

import openai  # kept for the expected signature, though unused
import rust_codecontests_utils as rcu


# ---------------------------------------------------------------------------
# Utilities to parse integers and extract I/O pairs from examples
def _ints(text: str) -> list[int]:
    return [int(x) for x in re.findall(r"-?\d+", text)]


def _extract_io(example: Any) -> tuple[str, str] | None:
    if isinstance(example, dict):
        for a, b in [("input", "output"), ("stdin", "stdout"), ("in", "out")]:
            if a in example and b in example:
                return str(example[a]), str(example[b])
    if isinstance(example, (list, tuple)) and len(example) >= 2:
        return str(example[0]), str(example[1])
    return None


def _detect_op(problem: dict[str, Any]) -> str | None:
    """
    If every public example's output equals sum/min/max of the ints in input,
    return the detected op name, else None.
    """
    key = next((k for k in ("examples", "public_tests") if k in problem), None)
    if not key:
        return None

    raw = problem[key]
    if isinstance(raw, dict):
        raw = list(raw.values())

    ops: dict[str, Callable[[list[int]], int]] = {
        "sum": sum,
        "min": min,
        "max": max,
    }
    possible = set(ops)
    for ex in raw:
        io = _extract_io(ex)
        if io is None:
            return None
        ins, outs = io
        in_nums, out_nums = _ints(ins), _ints(outs)
        if len(out_nums) != 1 or not in_nums:
            return None
        tgt = out_nums[0]
        possible = {op for op in possible if ops[op](in_nums) == tgt}
        if not possible:
            return None
    return next(iter(possible)) if possible else None


# ---------------------------------------------------------------------------
# Rust templates
TEMPLATE_SUM = r"""
use std::io::{self, Read};
fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let ans: i128 = s.split_whitespace().filter_map(|w| w.parse::<i128>().ok()).sum();
    println!("{}", ans);
}
"""
TEMPLATE_MIN = TEMPLATE_SUM.replace("sum()", "min().unwrap()")
TEMPLATE_MAX = TEMPLATE_SUM.replace("sum()", "max().unwrap()")
TEMPLATE_EMPTY = "fn main() {}\n"

OP_TEMPLATE = {"sum": TEMPLATE_SUM, "min": TEMPLATE_MIN, "max": TEMPLATE_MAX}


# ---------------------------------------------------------------------------
# The function the scorer imports
async def generate_solution(
    client: openai.AsyncOpenAI,       # unused, kept for signature compatibility
    semaphore: asyncio.Semaphore,     # unused
    problem: dict[str, Any],
) -> str:
    op = _detect_op(problem)
    if op:
        return OP_TEMPLATE[op].strip()
    return TEMPLATE_EMPTY


# ---------------------------------------------------------------------------
# Quick validator (optional)
async def _quick_check(
    path: str = "data/valid.jsonl",
    n: int = 200,
    max_conc: int = max(2, os.cpu_count() or 2),
):
    problems = [json.loads(line) for _, line in zip(range(n), open(path, "r"))]
    sem = asyncio.Semaphore(max_conc)
    solved = 0
    with tempfile.TemporaryDirectory() as scratch:
        coros = [
            rcu.evaluate_rust_code(
                sem, prob, await generate_solution(None, None, prob), scratch
            )
            for prob in problems
        ]
        for coro in asyncio.as_completed(coros):
            res = await coro
            if res["succeeded"]:
                solved += 1
    return solved / len(problems)


if __name__ == "__main__":
    ratio = asyncio.run(_quick_check())
    print(f"Solved ratio on sampled validation problems: {ratio:.4f}")
```

