    },
    {
        "description": "Problem: Given a list of n integers, output the maximum integer.\n\nConstraints:\n1 ≤ n ≤ 1e5\nEach integer is between -1e9 and 1e9",
        "solution": """use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

